<template><ForgeDialog title="Text encryption" description="Encrypt and decrypt text locally with a secret key." eyebrow="WORKSPACE / SECURITY" wide @close="emit('close')"><div class="enc-panel"><section><h3>Encrypt</h3><textarea v-model="plain" rows="6" placeholder="Text to encrypt" /><div class="enc-controls"><input v-model="secret" type="password" placeholder="Secret key" /><select v-model="algorithm"><option>AES</option><option>TripleDES</option><option>Rabbit</option><option>RC4</option></select></div><textarea :value="encrypted" readonly rows="4" placeholder="Encrypted output" /><button class="action-button" @click="copy(encrypted)">Copy encrypted</button></section><section><h3>Decrypt</h3><textarea v-model="cipher" rows="6" placeholder="Encrypted text" /><div class="enc-controls"><input v-model="decryptSecret" type="password" placeholder="Secret key" /><select v-model="decryptAlgorithm"><option>AES</option><option>TripleDES</option><option>Rabbit</option><option>RC4</option></select></div><textarea :value="decrypted" readonly rows="4" placeholder="Decrypted output" /><button class="action-button" @click="copy(decrypted)">Copy decrypted</button></section></div><template #footer><span class="website-help">Encryption runs locally. Keep your secret key safe.</span><button class="action-button" @click="clear">Clear</button></template></ForgeDialog></template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import { AES, RC4, Rabbit, TripleDES, enc } from 'crypto-js'
import ForgeDialog from './ForgeDialog.vue'
import { clipboard } from '@/util/NodeFn'
const emit=defineEmits<{close:[]}>(); const algos:any={AES,TripleDES,Rabbit,RC4}; const plain=ref('Lorem ipsum dolor sit amet'); const secret=ref('my secret key'); const algorithm=ref('AES'); const cipher=ref(''); const decryptSecret=ref('my secret key'); const decryptAlgorithm=ref('AES'); const encrypted=computed(()=>{try{return algos[algorithm.value].encrypt(plain.value,secret.value).toString()}catch{return ''}}); const decrypted=computed(()=>{try{return algos[decryptAlgorithm.value].decrypt(cipher.value,decryptSecret.value).toString(enc.Utf8)}catch{return ''}}); const copy=(value:string)=>clipboard.writeText(value); const clear=()=>{plain.value='';cipher.value=''}
</script>
<style scoped>.enc-panel{display:grid;grid-template-columns:1fr 1fr;gap:14px}.enc-panel section{display:grid;gap:9px}.enc-panel h3{margin:0;color:var(--pqt-text);font-size:13px}.enc-panel textarea,.enc-panel input,.enc-panel select{width:100%;padding:10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:11px/1.5 var(--pqt-font-mono)}.enc-panel textarea{resize:vertical}.enc-controls{display:grid;grid-template-columns:1fr 110px;gap:7px}</style>
